-- =============================================================
-- ADC 牙科连锁信息管理系统 —— 建表脚本（PostgreSQL 16）
-- 与课程报告 6.6 / 6.9 / 6.10 一一对应：16 张业务表 + 5 张技术支撑表
-- 方言差异：AUTO_INCREMENT → GENERATED BY DEFAULT AS IDENTITY；
--          TINYINT → SMALLINT；DATETIME → TIMESTAMP；COMMENT → COMMENT ON
-- =============================================================

CREATE EXTENSION IF NOT EXISTS btree_gist;

-- -------------------------------------------------------------
-- 一、组织与人员域
-- -------------------------------------------------------------

CREATE TABLE employee (
  employee_id  INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name    VARCHAR(30) NOT NULL,
  gender       CHAR(1)     NOT NULL,
  phone        VARCHAR(20) NOT NULL,
  hire_date    DATE        NOT NULL,
  status       VARCHAR(10) NOT NULL
);
COMMENT ON TABLE  employee            IS '员工';
COMMENT ON COLUMN employee.employee_id IS '员工编号';
COMMENT ON COLUMN employee.full_name   IS '姓名';
COMMENT ON COLUMN employee.status      IS '在职状态';

CREATE TABLE clinic (
  clinic_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_name  VARCHAR(40) NOT NULL,
  city         VARCHAR(20) NOT NULL,
  address      VARCHAR(80),
  phone        VARCHAR(20),
  open_date    DATE,
  chair_count  INTEGER,
  status       VARCHAR(10) NOT NULL
);
COMMENT ON TABLE  clinic           IS '诊所';
COMMENT ON COLUMN clinic.clinic_id IS '诊所编号';
COMMENT ON COLUMN clinic.status    IS '营业状态（营业/筹备/关闭）';

CREATE TABLE qualification (
  qualification_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  qualification_name VARCHAR(40) NOT NULL,
  issuing_authority  VARCHAR(60),
  valid_until        DATE
);
COMMENT ON TABLE qualification IS '资质';

CREATE TABLE dentist (
  employee_id  INTEGER PRIMARY KEY,
  license_no   VARCHAR(30) NOT NULL UNIQUE,
  specialty    VARCHAR(30),
  title        VARCHAR(20),
  CONSTRAINT fk_dentist_employee FOREIGN KEY (employee_id) REFERENCES employee(employee_id)
);
COMMENT ON TABLE  dentist            IS '牙医（主键即外键，子类表）';
COMMENT ON COLUMN dentist.license_no IS '执业证书编号';

CREATE TABLE receptionist (
  employee_id  INTEGER PRIMARY KEY,
  clinic_id    INTEGER,
  grade        VARCHAR(10),
  scope        VARCHAR(50),
  CONSTRAINT fk_receptionist_employee FOREIGN KEY (employee_id) REFERENCES employee(employee_id),
  CONSTRAINT fk_receptionist_clinic   FOREIGN KEY (clinic_id)   REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE receptionist IS '前台接待员（子类表）';

CREATE TABLE administrator (
  employee_id    INTEGER PRIMARY KEY,
  position_name  VARCHAR(30) NOT NULL,
  scope          VARCHAR(50),
  CONSTRAINT fk_admin_employee FOREIGN KEY (employee_id) REFERENCES employee(employee_id)
);
COMMENT ON TABLE administrator IS '总部管理者（子类表）';

CREATE TABLE dentist_clinic (
  dc_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id   INTEGER NOT NULL,
  clinic_id     INTEGER NOT NULL,
  schedule_note VARCHAR(50),
  is_primary    SMALLINT NOT NULL DEFAULT 0 CHECK (is_primary IN (0, 1)),
  CONSTRAINT uk_dentist_clinic UNIQUE (employee_id, clinic_id),
  CONSTRAINT fk_dc_employee FOREIGN KEY (employee_id) REFERENCES dentist(employee_id),
  CONSTRAINT fk_dc_clinic   FOREIGN KEY (clinic_id)   REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE dentist_clinic IS '牙医执业点（关联表）';

CREATE TABLE dentist_qualification (
  dq_id             INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id       INTEGER NOT NULL,
  qualification_id  INTEGER NOT NULL,
  obtain_date       DATE,
  certificate_no    VARCHAR(30),
  CONSTRAINT uk_dentist_qual UNIQUE (employee_id, qualification_id),
  CONSTRAINT fk_dq_employee FOREIGN KEY (employee_id)      REFERENCES dentist(employee_id),
  CONSTRAINT fk_dq_qual     FOREIGN KEY (qualification_id) REFERENCES qualification(qualification_id)
);
COMMENT ON TABLE dentist_qualification IS '牙医资质（关联表）';

-- -------------------------------------------------------------
-- 二、患者与诊疗域
-- -------------------------------------------------------------

CREATE TABLE patient (
  patient_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  full_name    VARCHAR(30) NOT NULL,
  gender       CHAR(1)     NOT NULL,
  birth_date   DATE,
  phone        VARCHAR(20) NOT NULL,
  email        VARCHAR(50),
  address      VARCHAR(80),
  wx_openid    VARCHAR(64) UNIQUE,
  created_date DATE        NOT NULL,
  note         VARCHAR(120)
);
COMMENT ON TABLE  patient            IS '患者';
COMMENT ON COLUMN patient.wx_openid  IS '微信 openid（小程序登录标识；到店患者可为空）';
COMMENT ON COLUMN patient.phone      IS '联系电话（建档查重的一项，不单独作识别键）';

CREATE TABLE allergen (
  allergen_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  allergen_name  VARCHAR(30) NOT NULL UNIQUE,
  category       VARCHAR(20),
  description    VARCHAR(120)
);
COMMENT ON TABLE allergen IS '过敏症（值表）';

CREATE TABLE treatment_item (
  item_id          INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  item_name        VARCHAR(40)  NOT NULL UNIQUE,
  standard_unit    DECIMAL(6,2) NOT NULL,
  unit_price       DECIMAL(10,2) NOT NULL,
  contraindication VARCHAR(80),
  is_active        SMALLINT NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  description      VARCHAR(120)
);
COMMENT ON TABLE  treatment_item                  IS '治疗项目（标准目录）';
COMMENT ON COLUMN treatment_item.unit_price       IS '当前标准单价；历史成交价快照在 visit_treatment';
COMMENT ON COLUMN treatment_item.contraindication IS '禁忌材料，用于与患者过敏症比对';

CREATE TABLE patient_allergy (
  record_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  patient_id        INTEGER NOT NULL,
  allergen_id       INTEGER NOT NULL,
  severity          VARCHAR(10) NOT NULL,
  reaction          VARCHAR(120),
  first_record_date DATE,
  CONSTRAINT uk_patient_allergen UNIQUE (patient_id, allergen_id),
  CONSTRAINT fk_pa_patient  FOREIGN KEY (patient_id)  REFERENCES patient(patient_id),
  CONSTRAINT fk_pa_allergen FOREIGN KEY (allergen_id) REFERENCES allergen(allergen_id)
);
COMMENT ON TABLE patient_allergy IS '患者过敏记录（关联表）';

CREATE TABLE appointment (
  appointment_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  appointment_no   VARCHAR(24) NOT NULL UNIQUE,
  patient_id       INTEGER NOT NULL,
  employee_id      INTEGER NOT NULL,
  clinic_id        INTEGER NOT NULL,
  appointment_time TIMESTAMP NOT NULL,
  expected_minutes INTEGER NOT NULL DEFAULT 30 CHECK (expected_minutes > 0),
  channel          VARCHAR(10) NOT NULL CHECK (channel IN ('电话', '到店', '小程序')),
  status           VARCHAR(10) NOT NULL CHECK (status IN ('待就诊', '已就诊', '未到诊', '已取消')),
  created_time     TIMESTAMP NOT NULL,
  cancel_reason    VARCHAR(60),
  CONSTRAINT fk_ap_patient  FOREIGN KEY (patient_id)  REFERENCES patient(patient_id),
  CONSTRAINT fk_ap_dentist  FOREIGN KEY (employee_id) REFERENCES dentist(employee_id),
  CONSTRAINT fk_ap_clinic   FOREIGN KEY (clinic_id)   REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE  appointment                IS '预约';
COMMENT ON COLUMN appointment.appointment_no IS '预约单号：诊所代码+日期+流水，全连锁唯一';
COMMENT ON COLUMN appointment.channel        IS '预约渠道：电话/到店/小程序，取消率按此拆分';

CREATE TABLE visit (
  visit_id         INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  appointment_id   INTEGER UNIQUE,
  patient_id       INTEGER NOT NULL,
  employee_id      INTEGER NOT NULL,
  clinic_id        INTEGER NOT NULL,
  arrival_time     TIMESTAMP NOT NULL,
  end_time         TIMESTAMP,
  chief_complaint  VARCHAR(200),
  diagnosis        VARCHAR(200),
  status           VARCHAR(10) NOT NULL CHECK (status IN ('进行中', '已完成')),
  recorded_time    TIMESTAMP NOT NULL,
  CONSTRAINT fk_visit_appointment FOREIGN KEY (appointment_id) REFERENCES appointment(appointment_id),
  CONSTRAINT fk_visit_patient     FOREIGN KEY (patient_id)     REFERENCES patient(patient_id),
  CONSTRAINT fk_visit_dentist     FOREIGN KEY (employee_id)    REFERENCES dentist(employee_id),
  CONSTRAINT fk_visit_clinic      FOREIGN KEY (clinic_id)      REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE  visit               IS '就诊（散客就诊的 appointment_id 为空）';
COMMENT ON COLUMN visit.status        IS '就诊阶段：进行中/已完成';
COMMENT ON COLUMN visit.appointment_id IS '来源预约，可空——walk-in 散客不补造预约';

CREATE TABLE visit_treatment (
  vt_id           INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  visit_id        INTEGER NOT NULL,
  item_id         INTEGER NOT NULL,
  tooth_code      CHAR(2),
  quantity        DECIMAL(8,2)  NOT NULL CHECK (quantity > 0),
  consumed_units  DECIMAL(8,2)  NOT NULL,
  unit_price      DECIMAL(10,2) NOT NULL,
  subtotal        DECIMAL(10,2) NOT NULL,
  executed_time   TIMESTAMP,
  CONSTRAINT ck_vt_fdi CHECK (tooth_code IS NULL OR tooth_code ~ '^[1-8][1-8]$'),
  CONSTRAINT fk_vt_visit FOREIGN KEY (visit_id) REFERENCES visit(visit_id),
  CONSTRAINT fk_vt_item  FOREIGN KEY (item_id)  REFERENCES treatment_item(item_id)
);
COMMENT ON TABLE  visit_treatment            IS '就诊治疗明细（聚合内实体，不可脱离就诊单独增删）';
COMMENT ON COLUMN visit_treatment.tooth_code IS '牙位（FDI 两位记法）；洁治等不分牙位的项目为空';
COMMENT ON COLUMN visit_treatment.unit_price IS '下单时的价格快照，不随目录调价变化';

CREATE TABLE statement (
  statement_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  statement_no   VARCHAR(24) NOT NULL UNIQUE,
  visit_id       INTEGER UNIQUE,
  patient_id     INTEGER NOT NULL,
  reversal_of_id INTEGER UNIQUE,
  issue_date     DATE NOT NULL,
  treatment_fee  DECIMAL(10,2) NOT NULL DEFAULT 0,
  material_fee   DECIMAL(10,2) NOT NULL DEFAULT 0,
  discount       DECIMAL(10,2) DEFAULT 0,
  total_due      DECIMAL(10,2) NOT NULL,
  payment_method VARCHAR(20),
  status         VARCHAR(10) NOT NULL DEFAULT '待出具'
                 CHECK (status IN ('待出具', '已出具', '待支付', '已结算', '已红冲')),
  paid_amount    DECIMAL(10,2) NOT NULL DEFAULT 0,
  payment_time   TIMESTAMP,
  claim_no       VARCHAR(30),
  CONSTRAINT fk_st_visit    FOREIGN KEY (visit_id)       REFERENCES visit(visit_id),
  CONSTRAINT fk_st_patient  FOREIGN KEY (patient_id)     REFERENCES patient(patient_id),
  CONSTRAINT fk_st_reversal FOREIGN KEY (reversal_of_id) REFERENCES statement(statement_id)
);
COMMENT ON TABLE  statement                IS '结算单（红字单以 reversal_of_id 指回原单）';
COMMENT ON COLUMN statement.reversal_of_id IS '红冲指向的原单；原单被冲后置为“已红冲”';

-- -------------------------------------------------------------
-- 三、技术支撑表（不属于问题域，为系统能跑而存在）
-- -------------------------------------------------------------

CREATE TABLE user_account (
  account_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id   INTEGER NOT NULL UNIQUE,
  username      VARCHAR(30) NOT NULL UNIQUE,
  password_hash VARCHAR(100) NOT NULL,
  role_code     VARCHAR(20) NOT NULL CHECK (role_code IN ('RECEPTIONIST', 'DENTIST', 'ADMIN')),
  status        VARCHAR(10) NOT NULL DEFAULT '启用',
  last_login_at TIMESTAMP,
  CONSTRAINT fk_ua_employee FOREIGN KEY (employee_id) REFERENCES employee(employee_id)
);
COMMENT ON TABLE  user_account               IS '员工账号';
COMMENT ON COLUMN user_account.password_hash IS 'BCrypt 口令哈希，不存明文';

CREATE TABLE audit_log (
  log_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  account_id INTEGER,
  action     VARCHAR(30) NOT NULL,
  entity     VARCHAR(30) NOT NULL,
  entity_id  INTEGER NOT NULL,
  detail     VARCHAR(500),
  ip         VARCHAR(45),
  created_at TIMESTAMP NOT NULL,
  CONSTRAINT fk_al_account FOREIGN KEY (account_id) REFERENCES user_account(account_id)
);
COMMENT ON TABLE audit_log IS '审计日志：谁、何时、对哪条记录、把什么改成了什么';

CREATE TABLE clinic_hours (
  hours_id   INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  clinic_id  INTEGER NOT NULL,
  weekday    SMALLINT NOT NULL CHECK (weekday BETWEEN 1 AND 7),
  open_time  TIME NOT NULL,
  close_time TIME NOT NULL,
  CONSTRAINT uk_clinic_weekday UNIQUE (clinic_id, weekday),
  CONSTRAINT ck_hours_order CHECK (close_time > open_time),
  CONSTRAINT fk_ch_clinic FOREIGN KEY (clinic_id) REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE clinic_hours IS '诊所营业时间（可约时段的下界）';

CREATE TABLE dentist_schedule (
  shift_id    INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  employee_id INTEGER NOT NULL,
  clinic_id   INTEGER NOT NULL,
  work_date   DATE NOT NULL,
  start_time  TIME NOT NULL,
  end_time    TIME NOT NULL,
  CONSTRAINT uk_dentist_shift UNIQUE (employee_id, work_date, start_time),
  CONSTRAINT ck_shift_order CHECK (end_time > start_time),
  CONSTRAINT fk_ds_dentist FOREIGN KEY (employee_id) REFERENCES dentist(employee_id),
  CONSTRAINT fk_ds_clinic  FOREIGN KEY (clinic_id)   REFERENCES clinic(clinic_id)
);
COMMENT ON TABLE dentist_schedule IS '牙医排班（可约时段的数据来源）';

CREATE TABLE payment (
  payment_id     BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  statement_id   INTEGER NOT NULL,
  amount         DECIMAL(10,2) NOT NULL,
  method         VARCHAR(20) NOT NULL,
  gateway_txn_no VARCHAR(40) UNIQUE,
  status         VARCHAR(10) NOT NULL CHECK (status IN ('成功', '失败', '已退款')),
  paid_at        TIMESTAMP,
  fail_reason    VARCHAR(100),
  CONSTRAINT fk_pay_statement FOREIGN KEY (statement_id) REFERENCES statement(statement_id)
);
COMMENT ON TABLE  payment              IS '支付流水（本期为到店收款，不接线上支付）';
COMMENT ON COLUMN payment.amount       IS '金额，退款为负';
COMMENT ON COLUMN payment.gateway_txn_no IS '收款凭据号，作为幂等键防重复入账';

-- -------------------------------------------------------------
-- 四、索引
-- -------------------------------------------------------------

CREATE INDEX idx_ap_dentist_time ON appointment (employee_id, appointment_time);
CREATE INDEX idx_ap_clinic_time  ON appointment (clinic_id, appointment_time);
CREATE INDEX idx_ap_patient_time ON appointment (patient_id, appointment_time);
CREATE INDEX idx_visit_clinic_time ON visit (clinic_id, recorded_time);
CREATE INDEX idx_vt_visit ON visit_treatment (visit_id);
CREATE INDEX idx_st_issue_date ON statement (issue_date);
CREATE INDEX idx_st_patient ON statement (patient_id);
CREATE INDEX idx_al_entity ON audit_log (entity, entity_id);
CREATE INDEX idx_al_created ON audit_log (created_at);
CREATE INDEX idx_ds_clinic_date ON dentist_schedule (clinic_id, work_date);
CREATE INDEX idx_payment_statement ON payment (statement_id);

-- -------------------------------------------------------------
-- 五、时段排他：同一牙医的时间区间不得重叠（取消的不占位）
--    报告 6.12「时段排他」一条的落点。唯一键挡不住区间重叠，靠 gist 排他约束。
-- -------------------------------------------------------------

ALTER TABLE appointment
  ADD CONSTRAINT ex_appointment_no_overlap
  EXCLUDE USING gist (
    employee_id WITH =,
    tsrange(
      appointment_time,
      appointment_time + (expected_minutes * INTERVAL '1 minute'),
      '[)'
    ) WITH &&
  )
  WHERE (status <> '已取消');

COMMENT ON CONSTRAINT ex_appointment_no_overlap ON appointment
  IS '同一牙医的时间区间不得重叠；已取消的预约不占位，可被重新预约';
